const P = (window.__P = {});
P.S = () => window.__ensemble.getState();
P.sleep = (ms) => new Promise((r) => setTimeout(r, ms));
P.frame = () => new Promise((r) => requestAnimationFrame(() => setTimeout(r, 0)));
P.q = (a, p) => { if (!a.length) return 0; const s = [...a].sort((x, y) => x - y); return s[Math.min(s.length - 1, Math.floor(p * (s.length - 1) + 0.5))]; };
P.r1 = (x) => Math.round(x * 10) / 10;
P.long = [];
try { new PerformanceObserver((l) => { for (const e of l.getEntries()) P.long.push({ t: e.startTime, d: e.duration }); }).observe({ type: 'longtask', buffered: true }); } catch (e) { P.longErr = String(e); }
P.longIn = (a, b) => { const l = P.long.filter((x) => x.t >= a && x.t <= b); return { n: l.length, total: Math.round(l.reduce((s, x) => s + x.d, 0)), max: Math.round(Math.max(0, ...l.map((x) => x.d))) }; };
P.perf = () => window.__ensemblePerf;
P.snap = () => ({ ...(P.perf()?.renders || {}), _commits: P.perf()?.commits || 0 });
P.diff = (a, b) => { const o = {}; for (const k in b) { const d = (b[k] || 0) - (a[k] || 0); if (d) o[k] = d; } return o; };
P.times = () => { const t = P.perf()?.times || {}; const o = {}; for (const k in t) { if (!t[k].length) continue; o[k] = { n: t[k].length, med: P.r1(P.q(t[k], 0.5)), p95: P.r1(P.q(t[k], 0.95)), max: P.r1(Math.max(...t[k])) }; t[k] = []; } return o; };
P.dom = () => document.getElementsByTagName('*').length;
P.heap = () => Math.round((performance.memory?.usedJSHeapSize || 0) / 1048576);
P.anims = () => { const a = document.getAnimations().filter((x) => x.playState === 'running'); const names = {}; for (const x of a) { const n = x.animationName || x.transitionProperty || 'other'; names[n] = (names[n] || 0) + 1; } return { n: a.length, names }; };
P.lead = () => { const s = P.S(); const c = s.chats.find((x) => x.id === s.chatId); return c?.leadId || s.settings.leadId || s.accounts[0]?.id; };
P.key = () => P.S().chatId + ':' + P.lead();
P.scroller = () => { const v = document.querySelector('[data-view-scope]'); return v && v.parentElement; };
P.working = () => { const s = P.S(); const pre = s.chatId + ':'; return Object.entries(s.agents).filter(([k, v]) => k.startsWith(pre) && v.phase !== 'idle' && v.phase !== 'error').length; };

// ---- a long chat: about 3,000 rows of realistic history on the lead ----
P.md = (i) => `## Step ${i}: what changed and why\n\nThe **checkout flow** now validates the card before it calls the payment API, so a declined card no longer leaves a half-made order. Three files changed; the tests for \`orders\` pass.\n\n- Moved the price maths into \`src/lib/price.ts\` so the page and the API agree\n- Added a retry with backoff for the webhook (max 3, then a notice)\n- Removed the old \`legacyTotal()\` helper, which nothing called\n\n| File | Lines | Why |\n|---|---:|---|\n| src/lib/price.ts | +84 | one place for the maths |\n| src/api/checkout.ts | +31 −12 | validate first |\n| tests/orders.test.ts | +46 | the declined-card case |\n\n\`\`\`ts\nexport function total(items: Line[], coupon?: Coupon): Money {\n  let sum = 0\n  for (const it of items) {\n    if (it.qty <= 0) continue\n    sum += it.price * it.qty\n  }\n  if (coupon?.kind === 'percent') sum = sum * (1 - coupon.value / 100)\n  if (coupon?.kind === 'fixed') sum = Math.max(0, sum - coupon.value)\n  const tax = Math.round(sum * TAX_RATE)\n  return { net: sum, tax, gross: sum + tax, currency: 'EUR' }\n}\n\nexport async function charge(order: Order): Promise<Charge> {\n  const card = await validate(order.card)\n  if (!card.ok) throw new Declined(card.reason)\n  return api.post('/charges', { amount: total(order.items).gross, card: card.token })\n}\n\`\`\`\n\nWhat is still uncertain: the webhook retry has only been tested against the sandbox, not live. Next I would run the full suite once more and open the page to check the totals by eye.`;
P.history = (n, leadId, agentIds, img) => {
  const out = []; let id = 0; const t0 = Date.now() - n * 4000; const ts = () => t0 + id * 4000;
  const push = (o) => { o.id = 'h' + id; o.ts = ts(); id++; out.push(o); };
  let i = 0;
  while (out.length < n) {
    i++;
    push({ kind: 'user', text: `Round ${i}: fix the checkout so a declined card does not leave an order behind, and show me the tests passing.` });
    push({ kind: 'thinking', text: 'Looking at how checkout builds the order first, then where the card is charged. The order row is written before the charge; that is the bug.', durationMs: 2400 });
    push({ kind: 'tool', name: 'Read', input: { file_path: 'src/api/checkout.ts' }, output: 'export async function checkout(req) {\n  const order = await db.orders.insert(req.body)\n  await charge(order)\n  return order\n}\n'.repeat(4), status: 'done', durationMs: 40 });
    push({ kind: 'tool', name: 'Grep', input: { pattern: 'legacyTotal', path: 'src' }, output: 'src/lib/old.ts:12: export function legacyTotal', status: 'done', durationMs: 120 });
    push({ kind: 'tool', name: 'Edit', input: { file_path: 'src/lib/price.ts', old_string: 'a', new_string: 'b' }, output: 'The file was updated.', status: 'done', durationMs: 30 });
    push({ kind: 'tool', name: 'Bash', input: { command: 'pnpm test orders', description: 'Run the order tests' }, output: ' PASS  tests/orders.test.ts (12 tests)\n Tests: 12 passed, 12 total\n Time: 3.1 s\n', status: 'done', durationMs: 3100 });
    if (i % 3 === 0) {
      const tid = 't' + i;
      push({ kind: 'delegate', taskId: tid, to: agentIds[i % agentIds.length], title: `Review checkout change ${i}`, brief: 'Read the diff for the checkout change and say what could go wrong, with the files.' });
      push({ kind: 'delegate', taskId: tid + 'b', to: agentIds[(i + 1) % agentIds.length], title: `Test declined cards ${i}`, brief: 'Run the order tests with a declined test card and show the result.' });
      push({ kind: 'peer', from: agentIds[i % agentIds.length], tag: 'result', taskId: tid, title: `Review checkout change ${i}`, status: 'done', text: 'Reviewed. Two notes: the retry needs a cap (it has one, 3), and `price.ts` should export the tax rate so the tests use the same one. Nothing blocking.' });
    }
    if (i % 5 === 0) push({ kind: 'image', path: img, caption: 'The checkout page after the change' });
    if (i % 7 === 0) push({ kind: 'notice', level: 'info', text: 'Claude 3 is running low on its session allowance; new work goes to others first.' });
    push({ kind: 'assistant', text: P.md(i) });
    push({ kind: 'turn', status: 'done', durationMs: 48000, steps: 14, tokens: 3200, model: 'claude-opus-5-5' });
  }
  return out.slice(0, n);
};
P.inject = (n) => {
  const s = P.S(); const k = P.key(); const lead = P.lead();
  const ids = s.accounts.map((a) => a.id).filter((x) => x !== lead);
  const hist = P.history(n, lead, ids.length ? ids : [lead], P.img);
  window.__ensemble.setState({ items: { ...s.items, [k]: [...hist, ...(s.items[k] || [])] } });
  return hist.length;
};

// ---- typing: keydown in the message box to the next drawn frame ----
P.type = async (n, gap) => {
  const ta = document.querySelector('.composer textarea'); if (!ta) return { error: 'no message box' };
  ta.focus();
  const toFrame = [], handler = [];
  const before = P.snap(); P.times();
  for (let i = 0; i < n; i++) {
    const ch = i % 7 === 6 ? ' ' : 'abcdefghijklmnopqrstuvwxyz'[i % 26];
    const t0 = performance.now();
    document.execCommand('insertText', false, ch);
    const t1 = performance.now();
    await P.frame();
    toFrame.push(performance.now() - t0); handler.push(t1 - t0);
    await P.sleep(gap);
  }
  const after = P.snap();
  ta.focus(); document.execCommand('selectAll'); document.execCommand('delete');
  return { keys: n, frameMedian: P.r1(P.q(toFrame, 0.5)), frameP95: P.r1(P.q(toFrame, 0.95)), frameWorst: P.r1(Math.max(...toFrame)), handlerMedian: P.r1(P.q(handler, 0.5)), handlerWorst: P.r1(Math.max(...handler)), renderMs: P.times(), rendersPerKey: Object.fromEntries(Object.entries(P.diff(before, after)).map(([k, v]) => [k, P.r1(v / n)])) };
};

// ---- one keystroke on its own: what draws ----
P.oneKey = async () => {
  const ta = document.querySelector('.composer textarea'); ta.focus();
  await P.frame(); const a = P.snap();
  document.execCommand('insertText', false, 'x');
  await P.frame(); await P.frame(); const b = P.snap();
  document.execCommand('delete');
  return P.diff(a, b);
};

// ---- scrolling the whole transcript, top to bottom and back, one step per frame ----
P.scroll = async (step) => {
  const el = P.scroller(); if (!el) return { error: 'no transcript' };
  P.times(); P.lastH = 0; el.scrollTop = el.scrollHeight; await P.frame(); await P.sleep(300);
  const deltas = []; const mounts = []; let lastR = 0; let last = 0; let px = 0; let clicks = 0; let going = true; let dir = -1;
  const t0 = performance.now();
  await new Promise((done) => {
    const tick = (t) => {
      const rr = P.perf()?.renders?.Row || 0;
      if (last) { deltas.push(t - last); mounts.push(rr - lastR); }
      last = t; lastR = rr;
      const before = el.scrollTop;
      if (dir < 0) {
        if (el.scrollTop <= 0) {
          const more = [...el.querySelectorAll('button')].find((b) => /Show earlier messages/.test(b.textContent));
          // A press that brings nothing more in is the end of what can be reached.
          if (more && el.scrollHeight !== P.lastH) { P.lastH = el.scrollHeight; more.click(); clicks++; } else dir = 1;
        } else el.scrollTop = Math.max(0, el.scrollTop - step);
      } else {
        if (el.scrollTop + el.clientHeight >= el.scrollHeight - 2) going = false;
        else el.scrollTop = el.scrollTop + step;
      }
      px += Math.abs(el.scrollTop - before);
      if (going && performance.now() - t0 < 240000) requestAnimationFrame(tick); else done();
    };
    requestAnimationFrame(tick);
  });
  const t1 = performance.now();
  const slowWith = deltas.filter((d, i) => d > 17.5 && mounts[i] > 0).length; const avg = (f) => { const x = deltas.filter((d, i) => f(mounts[i])); return P.r1(x.reduce((s, y) => s + y, 0) / Math.max(1, x.length)); };
  return { renderMs: P.times(), slowFramesWithNewRows: slowWith, avgFrameNoNewRows: avg((m) => m === 0), avgFrameNewRows: avg((m) => m > 0), frames: deltas.length, over16: deltas.filter((d) => d > 17.5).length, pctOver16: P.r1((100 * deltas.filter((d) => d > 17.5).length) / Math.max(1, deltas.length)), over50: deltas.filter((d) => d > 50).length, longest: Math.round(Math.max(0, ...deltas)), medianFrame: P.r1(P.q(deltas, 0.5)), px: Math.round(px), earlierClicks: clicks, seconds: P.r1((t1 - t0) / 1000), longTasks: P.longIn(t0, t1), dom: P.dom() };
};

P.window = async (ms) => {
  P.times(); const a = P.snap(); const t0 = performance.now(); const c0 = P.perf()?.commits || 0;
  await P.sleep(ms);
  const t1 = performance.now(); const b = P.snap();
  const per = Object.fromEntries(Object.entries(P.diff(a, b)).map(([k, v]) => [k, P.r1((v * 1000) / (t1 - t0))]));
  return { renderMs: P.times(), seconds: P.r1((t1 - t0) / 1000), commitsPerSec: P.r1((((P.perf()?.commits || 0) - c0) * 1000) / (t1 - t0)), rendersPerSec: per, longTasks: P.longIn(t0, t1), runningAnimations: P.anims(), working: P.working(), dom: P.dom(), heapMB: P.heap() };
};
// ---- the floor: the same scroll over a static copy of what is drawn, with no app work at all ----
P.control = async (step, frames) => {
  const src = document.querySelector('[data-view-scope]'); if (!src) return { error: 'no transcript' };
  const box = document.createElement('div');
  box.style.cssText = 'position:fixed;inset:0;overflow:auto;z-index:99999;background:var(--color-window, #f2f1ee)';
  const inner = document.createElement('div'); inner.className = src.className; let html = ''; for (let i = 0; i < 40; i++) html += src.innerHTML; inner.innerHTML = html; box.appendChild(inner); document.body.appendChild(box);
  await P.frame(); await P.sleep(300);
  const deltas = []; let last = 0;
  await new Promise((done) => { const tick = (t) => { if (last) deltas.push(t - last); last = t; box.scrollTop += step; if (deltas.length < frames && box.scrollTop + box.clientHeight < box.scrollHeight - 2) requestAnimationFrame(tick); else done(); }; requestAnimationFrame(tick); });
  box.remove();
  return { frames: deltas.length, pctOver16: P.r1((100 * deltas.filter((d) => d > 17.5).length) / Math.max(1, deltas.length)), over50: deltas.filter((d) => d > 50).length, longest: Math.round(Math.max(0, ...deltas)), staticNodes: inner.getElementsByTagName('*').length };
};

return 'perf helpers ' + !!window.__ensemblePerf + ' longtask ' + (P.longErr || 'ok');
